hl.workspace_rule({ workspace = "2", monitor = "desc:iiyama Corporation PL2480C 1245053601761", default = true })
hl.workspace_rule({ workspace = "3", monitor = "desc:BNQ BenQ GW2470 K1H08194019",            default = true })

-- Fallback for any other monitor
hl.monitor({
    output   = "",
    mode     = "preferred",
    position = "auto",
    scale    = "auto",
})


