-- See https://wiki.hypr.land/Configuring/Basics/Autostart/

-- Autostart necessary processes (like notifications daemons, status bars, etc.)
-- Or execute your favorite apps at launch like this:
--
-- hl.on("hyprland.start", function () 
--   hl.exec_cmd(terminal)
--   hl.exec_cmd("nm-applet")
--   hl.exec_cmd("waybar & hyprpaper & firefox")
-- end)

-- Session is started from SDDM via start-hyprland (no uwsm, graphical-session.target
-- stays inactive), so everything is started from here – one method for all daemons.
hl.on("hyprland.start", function ()
  -- Make the compositor env visible to D-Bus/systemd activated services (dunst, portals, ...)
  hl.exec_cmd("dbus-update-activation-environment --systemd WAYLAND_DISPLAY XDG_CURRENT_DESKTOP HYPRLAND_INSTANCE_SIGNATURE")

  -- Polkit agent (reset-failed: a start-limit from an earlier crashed session would block it)
  hl.exec_cmd("systemctl --user reset-failed hyprpolkitagent; systemctl --user start hyprpolkitagent")

  hl.exec_cmd("dunst")                  -- notifications (also D-Bus activatable as fallback)
  hl.exec_cmd("hyprpaper")              -- wallpaper, config: ~/.config/hypr/hyprpaper.conf
  hl.exec_cmd("hypridle")               -- lock before system sleep (no idle lock/dpms), config: ~/.config/hypr/hypridle.conf
  hl.exec_cmd("qs")                     -- Quickshell: bar + dropdowns on every output, config: ~/.config/quickshell/

  -- Tray applets: give the bar a moment to register the StatusNotifierWatcher first
  hl.exec_cmd("sleep 2; nm-applet --indicator")
  hl.exec_cmd("sleep 2; blueman-applet")

  -- Clipboard history (text + images), picked with mainMod + V. Text copies go through a hook that
  -- also drops whitespace around a single copied word (a password selected with the space after it).
  hl.exec_cmd("wl-paste --type text --watch $HOME/.local/bin/clipboard-store")
  hl.exec_cmd("wl-paste --type image --watch cliphist store")
end)


