-- Fully opaque, no blur: VMs, video players, browser (text/video must stay crisp)
hl.window_rule({
    name  = "opaque-vm-video-browser",
    match = { class = "^(virt-manager|looking-glass-client|qemu.*|mpv|vlc|org\\.videolan\\.VLC|io\\.mpv\\.Mpv|io\\.github\\.celluloid_player\\.Celluloid|firefox|chromium)$" },
    opaque  = true,
    no_blur = true,
})

-- Blurred translucent layers (Quickshell bar + its dropdowns, launcher, notifications)
hl.layer_rule({ name = "blur-qs-bar",      match = { namespace = "^qs-bar$" },          blur = true, ignore_alpha = 0.3 })
-- dropdowns animate themselves in QML
hl.layer_rule({ name = "blur-qs-dropdown", match = { namespace = "^qs-dropdown$" },     blur = true, ignore_alpha = 0.3, no_anim = true })
hl.layer_rule({ name = "blur-rofi",        match = { namespace = "^rofi$" },            blur = true, ignore_alpha = 0.3 })
hl.layer_rule({ name = "blur-notifications", match = { namespace = "^notifications$" }, blur = true, ignore_alpha = 0.3 })
